/**
 * Получить слово дня — детерминированно по дате, одинаково для всех игроков.
 */
export function getDailyWord(): string {
  const daysSinceEpoch = Math.floor(Date.now() / 86400000)
  const answers = VALID_ANSWERS
  return answers[daysSinceEpoch % answers.length]
}

/**
 * Получить случайное слово из списка проверенных ответов.
 */
export function getRandomWord(): string {
  const answers = VALID_ANSWERS
  return answers[Math.floor(Math.random() * answers.length)]
}

/**
 * Проверить, допустимо ли слово для ввода.
 * Проверяет наличие в расширенном словаре (27 000+ слов + сленг + маты),
 * а также разрешает любое корректное 5-буквенное русское слово с гласными.
 */
export function isValidWord(word: string): boolean {
  if (!word || word.length !== 5) return false
  const normalized = word.toUpperCase().replace(/Ё/g, 'Е')
  if (!/^[А-Я]{5}$/.test(normalized)) return false

  // 1. Быстрый поиск в основном словаре (27 000+ слов + сленг + маты)
  if (VALID_INPUT_WORDS.has(normalized)) return true

  // 2. Мягкая проверка для редких словоформ (содержит хотя бы 1 гласную и нет 4 одинаковых букв подряд)
  const vowels = /[АЕИОУЫЭЮЯ]/
  if (vowels.test(normalized) && !/(.)\1{3}/.test(normalized)) {
    return true
  }

  return false
}
